'use strict';
function isTartarModule(){return state.moduleId==='olympus2207-tartar';}
function moduleText(value){return typeof value==='string'?value:Array.isArray(value)?value.map(moduleText).join('\n'):value&&typeof value==='object'?Object.entries(value).map(([key,text])=>`${key}: ${moduleText(text)}`).join('\n'):String(value??'');}
function moduleSource(source){const text=moduleText(source);return text?`<div class="module-source">Источник: ${esc(text)}</div>`:'';}
function moduleSceneName(id){return state.scenes.find(s=>s.id===id)?.title||id;}
function moduleOverview(){if(!isTartarModule())return '';const issued=state.scenes.reduce((sum,s)=>sum+(Number(s.issuedXP)||0),0),total=state.scenes.reduce((sum,s)=>sum+(Number(s.xp)||0),0);return `<section class="panel module-overview"><div><div class="eyebrow">ОЛИМПУС 2207 · ТАРТАР</div><h2>От детства до Чистилища.</h2><p>Проверки, развилки и последствия взяты из твоего модуля. Отмечай исходы по ходу игры.</p></div><div class="module-xp"><strong>${issued}<small> / ${total} XP</small></strong><span>каждому участнику</span><a href="#reference" class="text-button">Правила и награды ↗</a></div><div class="module-overview-actions"><a href="#consequences" class="button ghost small">Факты и последствия ↗</a><a href="#scenes" class="button primary small">Открыть задания ↗</a></div></section>`;}
function moduleSceneDetails(s){if(!s)return '';if(!isTartarModule())return gmSceneSessionControls(s)+gmMissionActionList(s);const dependencies=(state.dependencies||[]).filter(d=>d.from===s.id||d.to===s.id);return `<div class="module-scene">${gmSceneSessionControls(s)}<div class="module-quest-meta"><span class="tag">${esc(s.act||'Задание модуля')}</span>${Number.isFinite(s.xp)?`<span class="module-reward">${s.xp} XP каждому</span>`:''}</div>${gmMissionActionList(s)}${s.completion?`<div class="module-completion"><div class="field-label">КОГДА ЦЕЛЬ ВЫПОЛНЕНА</div><p>${esc(s.completion)}</p></div>`:''}${s.xp?`<div class="module-award">${btn(s.issuedXP?'Награда уже выдана ✓':`Выдать ${s.xp} XP каждому`,'award-xp',s.issuedXP?'ghost small':'primary small',`data-id="${esc(s.id)}" ${s.issuedXP?'disabled':''}`)}<span>Один раз за задание. Бой входит в награду.</span></div>`:''}${Array.isArray(s.checks)&&s.checks.length?`<div class="module-checks"><h3>Проверки и развилки <span class="badge">${s.checks.length}</span></h3>${s.checks.map((c,i)=>`<details class="module-check" ${i===0?'open':''}><summary><span class="module-check-number">${String(i+1).padStart(2,'0')}</span>${esc(c.title||'Вариант решения')}</summary><div class="module-check-body"><div class="module-roll">${esc(c.check||'Смотри условия в исходном тексте задания.')}</div>${c.success?`<div class="module-result"><span>УСПЕХ</span><p>${esc(c.success)}</p></div>`:''}${c.failure?`<div class="module-result failure"><span>ПРОВАЛ / ДРУГОЙ ПУТЬ</span><p>${esc(c.failure)}</p></div>`:''}${c.detail?`<p class="module-source">Где взять: ${esc(c.detail)}</p>`:''}${c.notes?`<p class="muted prewrap">${esc(moduleText(c.notes))}</p>`:''}</div></details>`).join('')}</div>`:''}${Array.isArray(s.extras)&&s.extras.length?`<details class="module-extras"><summary>Условия, предметы и развязки</summary>${s.extras.map(text=>`<p class="prewrap">${esc(moduleText(text))}</p>`).join('')}</details>`:''}${dependencies.length?`<div class="module-dependencies"><h3>Связи с другими заданиями</h3>${dependencies.map(d=>{const other=d.from===s.id?d.to:d.from;return `<div class="module-dependency"><button class="text-button" data-action="open-scene" data-id="${esc(other)}">${d.from===s.id?'Далее':'Ранее'}: ${esc(moduleSceneName(other))} ↗</button><strong>${esc(d.label)}</strong><p>${esc(d.detail)}</p></div>`;}).join('')}</div>`:''}</div>`;}
function modulePeopleDirectory(){if(!isTartarModule())return '';return `<section class="panel module-people"><div class="panel-header"><h2 class="panel-title">Персонажи модуля <span class="badge">${state.characters.length}</span></h2></div><div class="module-people-search"><label class="sr-only" for="modulePeopleSearch">Найти персонажа по имени или роли</label><input class="input" type="search" id="modulePeopleSearch" data-module-people-search placeholder="Имя, роль или место в истории…" autocomplete="off"></div><div class="module-people-grid">${state.characters.map(c=>`<button class="module-person-button ${c.id===selectedChar?'selected':''}" data-action="select-char" data-id="${esc(c.id)}" data-search="${esc((c.name+' '+c.role+' '+moduleText(c.source)).toLocaleLowerCase('ru'))}"><span class="module-person-initial">${esc(c.name.slice(0,1))}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.role)}</small></span><span class="module-person-arrow">↗</span></button>`).join('')}</div><p class="module-directory-empty" hidden>Совпадений нет. Попробуй другое имя или роль.</p></section>`;}
function moduleCharacterExtra(c){if(!isTartarModule())return '';return `${c.combat?`<details class="module-combat"><summary>Боевой профиль · справка ведущему</summary><p class="prewrap">${esc(moduleText(c.combat))}</p></details>`:''}${moduleSource(c.source)}`;}
function reference(){const rules=state.rules||[];const quests=state.scenes.filter(s=>Number.isFinite(s.xp));return head('НАСТОЛЬНАЯ НАСТРОЙКА','Справочник ведущего.','Формулы, пороги, боевые профили и опыт из прикреплённого модуля.')+`<div class="module-reference-grid">${rules.map(r=>`<article class="panel module-rule"><h2>${esc(r.title)}</h2><p class="prewrap">${esc(r.text)}</p></article>`).join('')}</div>${quests.length?`<section class="panel module-ledger"><div class="panel-header"><h2 class="panel-title">Опыт по заданиям</h2><span class="tag">КАЖДОМУ УЧАСТНИКУ</span></div><div class="module-ledger-list">${quests.map(s=>`<div class="module-ledger-row"><button class="text-button" data-action="open-scene" data-id="${esc(s.id)}">${esc(s.title)} ↗</button><strong>${s.xp} XP</strong><span class="${s.issuedXP?'module-ledger-done':'muted'}">${s.issuedXP?'Выдано':'Не выдано'}</span></div>`).join('')}</div><div class="module-ledger-total"><strong>Всего: ${quests.reduce((sum,s)=>sum+s.xp,0)} XP каждому</strong><span>Награды разных способов одного задания не складываются.</span></div></section>`:''}<section class="panel module-source-panel"><h2>Исходный текст всегда рядом.</h2><p>Все задания, дополнительные условия и формулировки сохранены в «Рукописи». Карточки помогают вести игру, а исходный текст остаётся основой.</p><a class="button ghost" href="#manuscript">Открыть рукопись ↗</a></section>`;}
function consequences(){return head('РЕШЕНИЯ, КОТОРЫЕ ОТЗОВУТСЯ','Факты и последствия.','Отмечай только состоявшиеся события. «Не определено» сохраняет развилки открытыми.')+`<div class="module-flags">${(state.flags||[]).map(f=>`<article class="panel module-flag"><div><h2>${esc(f.title)}</h2><p>${esc(f.detail)}</p>${moduleSource(f.source)}</div><label class="module-flag-control"><span class="field-label">ЧТО ПРОИЗОШЛО</span><select class="input" data-flag-id="${esc(f.id)}" aria-label="${esc(f.title)}">${[['unknown','Не определено'],['yes','Да'],['no','Нет']].map(([v,t])=>`<option value="${v}" ${f.value===v?'selected':''}>${t}</option>`).join('')}</select></label></article>`).join('')}</div><section class="panel module-dependency-panel"><div class="panel-header"><h2 class="panel-title">Как задания влияют друг на друга</h2><span class="badge">${(state.dependencies||[]).length}</span></div><div class="module-dependency-list">${(state.dependencies||[]).map(d=>`<article class="module-dependency"><div class="module-dependency-path"><button class="text-button" data-action="open-scene" data-id="${esc(d.from)}">${esc(moduleSceneName(d.from))}</button><span>→</span><button class="text-button" data-action="open-scene" data-id="${esc(d.to)}">${esc(moduleSceneName(d.to))} ↗</button></div><strong>${esc(d.label)}</strong><p>${esc(d.detail)}</p></article>`).join('')}</div></section>`;}
function moduleClock(c){const active=c.active===true,steps=Array.isArray(c.steps)?c.steps:[];return `<div class="clock-card module-clock ${active?'running':'dormant'}"><button class="clock" style="--progress:${c.value/c.max*360}deg" data-action="clock-plus" data-id="${esc(c.id)}" ${!active||c.value===c.max?'disabled':''} aria-label="Продвинуть таймер ${esc(c.title)}: ${c.value} из ${c.max}"><span class="clock-inner">${c.value}<small>/${c.max}</small></span></button><div class="clock-copy"><div class="clock-title">${esc(c.title)}</div><div class="clock-label">${c.value===c.max?'Порог достигнут':active?'Отсчёт идёт':'Ожидает события'}${c.unit?' · шаг: '+esc(c.unit):''}</div><div class="clock-controls"><button type="button" data-action="clock-minus" data-id="${esc(c.id)}" ${c.value===0?'disabled':''} aria-label="Уменьшить таймер">−</button><button type="button" data-action="clock-plus" data-id="${esc(c.id)}" ${!active||c.value===c.max?'disabled':''} aria-label="Продвинуть таймер">+</button><button type="button" class="module-clock-toggle" data-action="toggle-module-clock" data-id="${esc(c.id)}">${active?'Пауза':'Начать'}</button></div><details class="module-clock-conditions"><summary>Когда запускать и что произойдёт</summary><p>${esc(c.activation||'Запускай только при наступлении описанного в модуле события.')}</p>${steps.length?`<ol>${steps.map((step,i)=>`<li class="${c.value>=(typeof step==='object'?Number(step.value??step.at)||i+1:i+1)?'reached':''}">${esc(typeof step==='object'?step.text||step.label||moduleText(step):step)}</li>`).join('')}</ol>`:''}<p><strong>Порог:</strong> ${esc(c.consequence)}</p>${moduleSource(c.source)}</details></div></div>`;}
function moduleAction(action,id){if(action==='award-xp'&&gmSessionActive()){gmSessionShowResults(id);return true;}if(action==='award-xp'){const s=state.scenes.find(s=>s.id===id);if(!s||!s.xp||s.issuedXP)return true;modal('Подтвердить выполнение задания',`<div class="eyebrow">${esc(s.title)}</div><p>${esc(s.completion||'Цель задания выполнена и сдача подтверждена.')}</p><label class="checkbox-label"><input type="checkbox" name="confirmed" required> Цель выполнена; условия сдачи и награды соблюдены.</label><p class="muted">${s.xp} XP каждому участнику. Опыт за бой уже включён; повторной награды за другой способ нет.</p>`,form=>{if(!form.has('confirmed'))return;if(s.issuedXP){closeModal();return;}s.issuedXP=s.xp;record(`Задание «${s.title}»: выдано ${s.xp} XP каждому участнику. Условия завершения подтверждены ведущим.`,'Опыт');save();closeModal();render();toast('Награда записана один раз.');},btn('Отмена','close-modal','ghost')+'<button class="button primary" type="submit">Подтвердить и выдать XP</button>');return true;}
if(action==='toggle-module-clock'){const c=state.clocks.find(c=>c.id===id);if(!c)return true;c.active=!c.active;record((c.active?'Запущен':'Приостановлен')+' таймер: '+c.title+'. '+(c.unit?'Один шаг: '+c.unit+'. ':''),'Таймер');save();render();return true;}
if(action==='reset-module'){confirmDialog('Вернуться к началу «Тартара»?','Текущая история будет сохранена отдельной локальной копией. Модуль откроется с исходными заданиями, нераскрытыми тайнами и невыданным опытом.',()=>{try{localStorage.setItem(KEY+'-archive-'+new Date().toISOString(),JSON.stringify(state));}catch{toast('Не удалось сохранить копию. Скачай резервную копию перед сбросом.');return;}download('niti-before-reset.json',JSON.stringify(state,null,2));state=initial();selectedScene=state.current;selectedChar=state.characters[0]?.id;save();},'Открыть исходный модуль');return true;}
if(action==='legacy-backup'){try{const raw=localStorage.getItem('niti-storydesk-v1');if(raw){download('niti-previous-story.json',raw);toast('Предыдущая история скачана.');}else toast('Предыдущей истории в этом браузере нет.');}catch{toast('Хранилище браузера недоступно.');}return true;}return false;}
document.addEventListener('input',event=>{if(!event.target.matches('[data-module-people-search]'))return;const query=event.target.value.trim().toLocaleLowerCase('ru'),root=event.target.closest('.module-people');let visible=0;root.querySelectorAll('.module-person-button').forEach(button=>{const show=button.dataset.search.includes(query);button.hidden=!show;if(show)visible++;});const empty=root.querySelector('.module-directory-empty');if(empty)empty.hidden=visible!==0;});
document.addEventListener('change',event=>{const id=event.target.dataset.flagId;if(!id||!['unknown','yes','no'].includes(event.target.value))return;const flag=(state.flags||[]).find(f=>f.id===id);if(!flag)return;flag.value=event.target.value;record(`${flag.title}: ${{unknown:'не определено',yes:'да',no:'нет'}[flag.value]}.`,'Факт');save();});

function modulePublicHook(s){if(!isTartarModule()||s.id!=='q12')return s.hook;const flag=(state.flags||[]).find(f=>f.id==='guard-survived'||(/охранник/i.test(f.title)&&/спас|выжил/i.test(f.title)));if(flag?.value==='yes')return 'Обвиняющий охранник у западного поста заявляет, что герои открыли проход, и требует бросить всё и стоять на месте.';if(flag?.value==='no')return s.hook;return 'У западного поста охранник требует: «Бросай всё и стой на месте». Героям предъявляют обвинение.';}
function moduleRestorePanel(){let legacy=false;try{legacy=!!localStorage.getItem('niti-storydesk-v1');}catch{}return `<section class="panel module-source-panel module-restore-panel"><h2>Исходный модуль «Тартар»</h2><p>Можно заново открыть подготовленные задания и связи. Перед заменой текущая история сохраняется отдельной локальной копией в этом браузере; резервную копию для другого устройства скачивай отдельно.</p><div class="scene-actions">${btn('Открыть модуль с начала','reset-module','ghost')}${legacy?btn('↓ Скачать предыдущую историю','legacy-backup','ghost'):''}</div></section>`;}
function validModuleState(s){if(s.moduleId&&typeof s.moduleId!=='string')return false;const checks=[['dependencies',x=>x&&['from','to','label','detail'].every(k=>typeof x[k]==='string')&&s.scenes.some(y=>y.id===x.from)&&s.scenes.some(y=>y.id===x.to)],['flags',x=>x&&['id','title','detail','source'].every(k=>typeof x[k]==='string')&&['unknown','yes','no'].includes(x.value)],['rules',x=>x&&typeof x.title==='string'&&typeof x.text==='string']];for(const[k,test]of checks)if(s[k]!==undefined&&(!Array.isArray(s[k])||!s[k].every(test)))return false;return s.scenes.every(x=>(x.rewardConfig===undefined||(typeof window.gmSceneRewardValid==='function'&&window.gmSceneRewardValid(x.rewardConfig)))&&(x.actionOutcomes===undefined||(Array.isArray(x.actionOutcomes)&&x.actionOutcomes.length<=2000&&new Set(x.actionOutcomes.map(c=>c&&JSON.stringify([c.actionId,c.session]))).size===x.actionOutcomes.length&&x.actionOutcomes.every(c=>c&&['actionId','actionLabel','date','detail'].every(k=>typeof c[k]==='string')&&c.actionId&&['success','failure','unplayed'].includes(c.outcome)&&Number.isInteger(c.session)&&c.session>=1)))&&(x.actionChecks===undefined||(Array.isArray(x.actionChecks)&&x.actionChecks.length<=2000&&new Set(x.actionChecks.map(c=>c?.id)).size===x.actionChecks.length&&x.actionChecks.every(c=>c&&['id','check','success','failure','notes'].every(k=>typeof c[k]==='string'))))&&(x.xp===undefined||(Number.isFinite(x.xp)&&x.xp>=0))&&(x.issuedXP===undefined||(Number.isFinite(x.issuedXP)&&x.issuedXP>=0))&&(x.checks===undefined||(Array.isArray(x.checks)&&x.checks.every(c=>c&&['title','check','success','failure'].every(k=>typeof c[k]==='string'))))&&(x.extras===undefined||(Array.isArray(x.extras)&&x.extras.every(c=>typeof c==='string'))))&&s.clocks.every(x=>(x.active===undefined||typeof x.active==='boolean')&&(x.steps===undefined||(Array.isArray(x.steps)&&x.steps.every(t=>t&&Number.isInteger(t.at)&&typeof t.label==='string'))));}
